def add_link(apps, schema_editor):
    """Menu item "Quiz" right after "Typing" (the menu is ordered by tree)."""
    items = apps.get_model('judge', 'NavigationBar').objects.using(schema_editor.connection.alias)
    if items.filter(key='quiz').exists():
        return
    previous = items.filter(key='typing', parent=None).first() or items.filter(key='sandbox', parent=None).first()
    if previous is None:
        tree_id = (items.aggregate(m=Max('tree_id'))['m'] or 0) + 1
    else:
        tree_id = previous.tree_id + 1
        items.filter(tree_id__gte=tree_id).update(tree_id=F('tree_id') + 1)
    items.create(order=6, key='quiz', label='Quiz', path='/quiz/', regex='^/quiz',
                 lft=1, rght=2, tree_id=tree_id, level=0)


def remove_link(apps, schema_editor):
    apps.get_model('judge', 'NavigationBar').objects.using(schema_editor.connection.alias).filter(key='quiz').delete()


